template<typename... Args>
UINT CalculateNumMipLevels(Args... dimensions) {
  UINT maximum = (std::max)({static_cast<UINT>(dimensions)...});
  UINT levels = 0;
  do { ++levels; maximum >>= 1; } while (maximum);
  return levels;
}
