template<bool Volume, bool EnableSync>
void exercise(HRESULT backendResult, bool timedOut, bool createResponses, bool allResponses, UINT levels) {
  require(!state.live, "previous wrapper leaked");
  state = {};
  state.response = backendResult;
  state.timedOut = timedOut;
  state.createResponses = createResponses;
  state.allResponses = allResponses;
  const bool wait = createResponses || allResponses;
  const HRESULT expected = wait ? (timedOut ? D3DERR_INVALIDCALL : backendResult) : D3D_OK;
  state.requireNullOnRelease = FAILED(expected);
  Direct3DDevice9Ex_LSS<EnableSync> device;
  VolumeInterface* volume = nullptr;
  CubeInterface* cube = nullptr;
  state.outputIsNull = [&] { return Volume ? volume == nullptr : cube == nullptr; };
  HRESULT actual;
  if constexpr (Volume) {
    actual = device.CreateVolumeTexture(16, 8, 4, levels, D3DUSAGE_DYNAMIC,
      D3DFMT_A8R8G8B8, D3DPOOL_DEFAULT, &volume, nullptr);
  } else {
    actual = device.CreateCubeTexture(16, levels, D3DUSAGE_DYNAMIC,
      D3DFMT_A8R8G8B8, D3DPOOL_DEFAULT, &cube, nullptr);
  }
  require(actual == expected, "creation HRESULT changed");
  require(state.waits == static_cast<unsigned>(wait) &&
    state.pops == static_cast<unsigned>(wait && !timedOut), "response consumption changed");
  require(state.tracked == 1 && !state.messages.empty(), "wrapper or create command missing");
  const auto create = state.messages.front();
  const UINT expectedLevels = levels ? levels : 5;
  const auto& descriptor = state.descriptor;
  require(descriptor.Width == 16 && descriptor.Height == (Volume ? 8u : 16u) &&
    descriptor.Depth == (Volume ? 4u : 6u) && descriptor.Levels == expectedLevels &&
    descriptor.Usage == D3DUSAGE_DYNAMIC && descriptor.Format == D3DFMT_A8R8G8B8 &&
    descriptor.Pool == D3DPOOL_DEFAULT, "texture descriptor changed");
  const std::vector<uint64_t> expectedArguments = Volume ?
    std::vector<uint64_t>{16, 8, 4, expectedLevels, D3DUSAGE_DYNAMIC, D3DFMT_A8R8G8B8, D3DPOOL_DEFAULT, 0x1234} :
    std::vector<uint64_t>{16, expectedLevels, D3DUSAGE_DYNAMIC, D3DFMT_A8R8G8B8, D3DPOOL_DEFAULT, 0x1234};
  require(create.command == (Volume ? Commands::IDirect3DDevice9Ex_CreateVolumeTexture :
    Commands::IDirect3DDevice9Ex_CreateCubeTexture) && create.resource == 77 &&
    create.arguments == expectedArguments, "creation command arguments changed");
  if (FAILED(expected)) {
    require(state.outputIsNull() && state.live == 0 && state.releases == 1,
      "failed creation retained its output or wrapper");
  } else {
    require(!state.outputIsNull() && state.live == 1 && state.releases == 0 && state.messages.size() == 1,
      "successful creation lost caller ownership");
    if constexpr (Volume) { volume->Release(); } else { cube->Release(); }
    require(state.live == 0 && state.releases == 1, "successful wrapper cleanup changed");
  }
  const bool destroy = SUCCEEDED(expected) || timedOut;
  require(state.messages.size() == (destroy ? 2u : 1u),
    "explicit failure sent Destroy, or unresolved/successful creation omitted it");
  if (destroy) {
    const auto& destruction = state.messages.back();
    require(destruction.command == (Volume ? Commands::IDirect3DVolumeTexture9_Destroy :
      Commands::IDirect3DCubeTexture9_Destroy) && destruction.resource == 0x1234 &&
      destruction.uid > create.uid, "Destroy was not ordered after Create for the same resource");
  }
}

template<bool Volume, bool EnableSync>
void runCases() {
  for (const UINT levels : {0u, 3u}) {
    for (const auto error : {D3DERR_INVALIDCALL, D3DERR_OUTOFVIDEOMEMORY, E_OUTOFMEMORY}) {
      exercise<Volume, EnableSync>(error, false, true, false, levels);
      exercise<Volume, EnableSync>(error, false, false, true, levels);
    }
    exercise<Volume, EnableSync>(D3D_OK, true, true, false, levels);
    exercise<Volume, EnableSync>(D3D_OK, true, false, true, levels);
    exercise<Volume, EnableSync>(D3D_OK, false, true, false, levels);
    exercise<Volume, EnableSync>(D3D_OK, false, false, true, levels);
    // Disabled responses preserve asynchronous ownership even if the fake backend fails.
    exercise<Volume, EnableSync>(D3DERR_OUTOFVIDEOMEMORY, false, false, false, levels);
  }
  for (unsigned i = 0; i < 1000; ++i) {
    exercise<Volume, EnableSync>(D3DERR_OUTOFVIDEOMEMORY, false, true, false, 1);
  }
  state = {};
  Direct3DDevice9Ex_LSS<EnableSync> device;
  const auto result = Volume ?
    device.CreateVolumeTexture(16, 8, 4, 1, 0, D3DFMT_A8R8G8B8, D3DPOOL_DEFAULT, nullptr, nullptr) :
    device.CreateCubeTexture(16, 1, 0, D3DFMT_A8R8G8B8, D3DPOOL_DEFAULT, nullptr, nullptr);
  require(result == D3DERR_INVALIDCALL && !state.tracked && state.messages.empty(),
    "null output changed validation or created a resource");
}

int main() {
  try {
    runCases<true, false>();
    runCases<false, false>();
    runCases<true, true>();
    runCases<false, true>();
    std::puts("PASS: actual volume/cube creation, cancellation and destruction; HRESULT/output/ownership, explicit failure versus timeout, sync/async responses, wire fields and mip levels.");
    return 0;
  } catch (const std::exception& error) {
    std::fprintf(stderr, "%s\n", error.what());
    return 1;
  }
}
